/* ==========================================================
   Universal submenu scrolling and flexible card sizing
   ========================================================== */

/*
 * Every submenu is constrained to the visible right-hand area.
 * Individual lists and detail screens become scrollable whenever
 * their contents exceed the available vertical space.
 */
.frame-helm-action-column {
  overflow: hidden;
}

.frame-helm-action-column > .frame-helm-action-panel {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  width: 100%;
  height: 100%;
  min-height: 0;
  max-height: 100%;
  overflow: hidden;
  padding-bottom: 0;
  clip-path: none;
}

.frame-helm-action-column .frame-helm-section-heading,
.frame-helm-action-column .frame-helm-quick-budget,
.frame-helm-action-column .frame-helm-full-budget {
  flex: 0 0 auto;
}

/*
 * Category menus, Quick Action menus, Full Action menus,
 * Special Actions, Reactions, and Protocols all use these lists.
 */
.frame-helm-action-column .frame-helm-category-list,
.frame-helm-action-column .frame-helm-action-list {
  flex: 1 1 auto;
  min-height: 0;
  max-height: 100%;
  overflow-y: auto;
  overflow-x: hidden;
  padding-right: 0.5rem;
  padding-bottom: 2.75rem;
  scrollbar-gutter: stable;
}

/*
 * Movement uses several sibling sections rather than one action list,
 * so the complete Movement panel owns its vertical scrollbar.
 */
.frame-helm-action-column > .frame-helm-movement-panel {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  width: 100%;
  height: 100%;
  min-height: 0;
  max-height: 100%;
  overflow-y: auto;
  overflow-x: hidden;
  padding-right: 0.55rem;
  padding-bottom: 3rem;
  scrollbar-gutter: stable;
}

.frame-helm-movement-panel .frame-helm-section-heading {
  flex: 0 0 auto;
}

.frame-helm-movement-panel .frame-helm-movement-speed-setup,
.frame-helm-movement-panel .frame-helm-movement-modes,
.frame-helm-movement-panel .frame-helm-movement-tracker {
  flex: 0 0 auto;
  width: 100%;
  height: auto;
  max-height: none;
  overflow: visible;
}

.frame-helm-movement-panel .frame-helm-movement-modes {
  padding-bottom: 0.8rem;
}

.frame-helm-movement-panel .frame-helm-movement-tracker {
  margin-bottom: 1rem;
}

/*
 * Quick and Full Action confirmation screens may also grow taller
 * than the visible UI. Give each its own scrolling region.
 */
.frame-helm-action-column .frame-helm-quick-detail,
.frame-helm-action-column .frame-helm-full-detail {
  flex: 1 1 auto;
  width: 100%;
  min-height: 0;
  max-height: 100%;
  overflow-y: auto;
  overflow-x: hidden;
  padding-right: 0.5rem;
  padding-bottom: 2.5rem;
  scrollbar-gutter: stable;
  clip-path: none;
}

/*
 * Grid rows must derive their height from the tallest card in that
 * row. This applies to every category and submenu, not only Full
 * Actions.
 */
.frame-helm-action-column .frame-helm-category-list,
.frame-helm-action-column .frame-helm-action-list {
  grid-auto-rows: max-content;
  align-content: start;
  align-items: start;
  row-gap: 0.6rem;
  column-gap: 0.6rem;
}

/*
 * All selectable submenu cards grow naturally to contain names,
 * descriptions, restrictions, and disabled-state explanations.
 */
.frame-helm-action-column .frame-helm-category-button,
.frame-helm-action-column .frame-helm-action-button,
.frame-helm-action-column .frame-helm-quick-choice,
.frame-helm-action-column .frame-helm-full-choice,
.frame-helm-action-column .frame-helm-movement-mode,
.frame-helm-action-column .frame-helm-quick-execute-button,
.frame-helm-action-column .frame-helm-full-execute-button {
  align-self: start;
  width: 100%;
  height: auto !important;
  min-height: 4rem;
  max-height: none;
  overflow: visible;
  padding-top: 0.65rem;
  padding-bottom: 0.65rem;
  white-space: normal;
}

.frame-helm-action-column .frame-helm-category-button,
.frame-helm-action-column .frame-helm-action-button,
.frame-helm-action-column .frame-helm-quick-choice,
.frame-helm-action-column .frame-helm-full-choice,
.frame-helm-action-column .frame-helm-movement-mode {
  align-items: flex-start;
}

.frame-helm-action-column .frame-helm-category-button > i:first-child,
.frame-helm-action-column .frame-helm-action-button > i:first-child,
.frame-helm-action-column .frame-helm-movement-mode > i,
.frame-helm-action-column .frame-helm-category-arrow {
  margin-top: 0.2rem;
}

/*
 * Text containers may wrap to as many lines as necessary. Remove
 * inherited clipping, ellipsis, fixed-height, and nowrap behavior.
 */
.frame-helm-action-column .frame-helm-category-copy,
.frame-helm-action-column .frame-helm-action-copy,
.frame-helm-action-column .frame-helm-movement-mode > span,
.frame-helm-action-column .frame-helm-quick-execute-button > span,
.frame-helm-action-column .frame-helm-full-execute-button > span {
  align-self: stretch;
  min-width: 0;
  height: auto;
  max-height: none;
  overflow: visible;
}

.frame-helm-action-column .frame-helm-category-copy strong,
.frame-helm-action-column .frame-helm-category-copy small,
.frame-helm-action-column .frame-helm-action-copy strong,
.frame-helm-action-column .frame-helm-action-copy small,
.frame-helm-action-column .frame-helm-action-reason,
.frame-helm-action-column .frame-helm-movement-mode strong,
.frame-helm-action-column .frame-helm-movement-mode small,
.frame-helm-action-column .frame-helm-movement-mode em,
.frame-helm-action-column .frame-helm-quick-execute-button strong,
.frame-helm-action-column .frame-helm-quick-execute-button small,
.frame-helm-action-column .frame-helm-full-execute-button strong,
.frame-helm-action-column .frame-helm-full-execute-button small {
  display: block;
  width: 100%;
  max-width: 100%;
  height: auto;
  max-height: none;
  overflow: visible;
  white-space: normal;
  overflow-wrap: anywhere;
  word-break: normal;
  text-overflow: clip;
}

.frame-helm-action-column .frame-helm-category-copy strong,
.frame-helm-action-column .frame-helm-action-copy strong,
.frame-helm-action-column .frame-helm-movement-mode strong,
.frame-helm-action-column .frame-helm-quick-execute-button strong,
.frame-helm-action-column .frame-helm-full-execute-button strong {
  line-height: 1.18;
}

.frame-helm-action-column .frame-helm-category-copy small,
.frame-helm-action-column .frame-helm-action-copy small,
.frame-helm-action-column .frame-helm-movement-mode small,
.frame-helm-action-column .frame-helm-movement-mode em,
.frame-helm-action-column .frame-helm-quick-execute-button small,
.frame-helm-action-column .frame-helm-full-execute-button small {
  margin-top: 0.25rem;
  line-height: 1.35;
}

.frame-helm-action-column .frame-helm-action-reason {
  margin-top: 0.35rem;
  line-height: 1.3;
}

/*
 * Requirements inside Quick and Full detail screens must also grow
 * freely when their explanations wrap onto multiple lines.
 */
.frame-helm-action-column .frame-helm-quick-requirement,
.frame-helm-action-column .frame-helm-full-requirement,
.frame-helm-action-column .frame-helm-no-actions {
  flex: 0 0 auto;
  width: 100%;
  height: auto;
  min-height: 3rem;
  max-height: none;
  overflow: visible;
  white-space: normal;
}

.frame-helm-action-column .frame-helm-quick-requirement span,
.frame-helm-action-column .frame-helm-full-requirement span,
.frame-helm-action-column .frame-helm-no-actions p {
  min-width: 0;
  overflow: visible;
  white-space: normal;
  overflow-wrap: anywhere;
  text-overflow: clip;
}

/*
 * Add clearance after the final grid row so its border and text can
 * be scrolled fully above the bottom edge of the window.
 */
.frame-helm-action-column .frame-helm-category-list::after,
.frame-helm-action-column .frame-helm-action-list::after {
  display: block;
  grid-column: 1 / -1;
  width: 100%;
  height: 1.75rem;
  content: "";
}

/* ==========================================================
   Universal cockpit scrollbars
   ========================================================== */

.frame-helm-action-column > .frame-helm-movement-panel,
.frame-helm-action-column .frame-helm-category-list,
.frame-helm-action-column .frame-helm-action-list,
.frame-helm-action-column .frame-helm-quick-detail,
.frame-helm-action-column .frame-helm-full-detail {
  scrollbar-width: thin;
  scrollbar-color: var(--fh-cyan) rgba(2, 11, 14, 0.72);
}

.frame-helm-action-column > .frame-helm-movement-panel::-webkit-scrollbar,
.frame-helm-action-column .frame-helm-category-list::-webkit-scrollbar,
.frame-helm-action-column .frame-helm-action-list::-webkit-scrollbar,
.frame-helm-action-column .frame-helm-quick-detail::-webkit-scrollbar,
.frame-helm-action-column .frame-helm-full-detail::-webkit-scrollbar {
  width: 9px;
}

.frame-helm-action-column > .frame-helm-movement-panel::-webkit-scrollbar-track,
.frame-helm-action-column .frame-helm-category-list::-webkit-scrollbar-track,
.frame-helm-action-column .frame-helm-action-list::-webkit-scrollbar-track,
.frame-helm-action-column .frame-helm-quick-detail::-webkit-scrollbar-track,
.frame-helm-action-column .frame-helm-full-detail::-webkit-scrollbar-track {
  border-left: 1px solid var(--fh-cyan-muted);
  background: rgba(2, 11, 14, 0.72);
}

.frame-helm-action-column > .frame-helm-movement-panel::-webkit-scrollbar-thumb,
.frame-helm-action-column .frame-helm-category-list::-webkit-scrollbar-thumb,
.frame-helm-action-column .frame-helm-action-list::-webkit-scrollbar-thumb,
.frame-helm-action-column .frame-helm-quick-detail::-webkit-scrollbar-thumb,
.frame-helm-action-column .frame-helm-full-detail::-webkit-scrollbar-thumb {
  border: 2px solid rgba(2, 11, 14, 0.88);
  background: var(--fh-cyan);
}

/* ==========================================================
   Narrow-window fallback
   ========================================================== */

@media (max-width: 820px) {
  .frame-helm-action-column {
    overflow: visible;
  }

  .frame-helm-action-column > .frame-helm-action-panel,
  .frame-helm-action-column > .frame-helm-movement-panel,
  .frame-helm-action-column .frame-helm-category-list,
  .frame-helm-action-column .frame-helm-action-list,
  .frame-helm-action-column .frame-helm-quick-detail,
  .frame-helm-action-column .frame-helm-full-detail {
    width: 100%;
    height: auto;
    min-height: 0;
    max-height: none;
    overflow: visible;
    padding-right: 0;
  }

  .frame-helm-action-column > .frame-helm-movement-panel {
    padding-bottom: 1rem;
  }

  .frame-helm-action-column .frame-helm-category-button,
  .frame-helm-action-column .frame-helm-action-button,
  .frame-helm-action-column .frame-helm-quick-choice,
  .frame-helm-action-column .frame-helm-full-choice,
  .frame-helm-action-column .frame-helm-movement-mode,
  .frame-helm-action-column .frame-helm-quick-execute-button,
  .frame-helm-action-column .frame-helm-full-execute-button {
    width: 100%;
  }
}
